"use client";

export { MobileMenu } from "./MobileMenuContext";
export type { MobileMenuProps } from "./MobileMenuContext";
export { MobileMenuContent } from "./MobileMenuContent";
export type { MobileMenuContentProps } from "./MobileMenuContent";
export { MobileMenuClose, MobileMenuTrigger } from "./MobileMenuControls";
export type {
  MobileMenuCloseProps,
  MobileMenuTriggerProps,
} from "./MobileMenuControls";
export {
  MobileMenuHeader,
  MobileMenuLink,
  MobileMenuNav,
  MobileMenuTitle,
} from "./MobileMenuSections";
export type {
  MobileMenuHeaderProps,
  MobileMenuLinkProps,
  MobileMenuNavProps,
  MobileMenuTitleProps,
} from "./MobileMenuSections";

"use client";

import type { HTMLAttributes } from "react";
import { forwardRef, useRef } from "react";
import { createPortal } from "react-dom";
import { cn, composeRefs, swirskiAttrs } from "../../system";
import { OverlayParentContext, useModalOverlay } from "../../system/overlay";
import { usePortalRoot } from "../../hooks/use-portal-root/usePortalRoot";
import type { NavbarSize, NavbarTone, NavbarVariant } from "./Navbar";
import { useMobileMenu } from "./MobileMenuContext";

export type MobileMenuContentProps = HTMLAttributes<HTMLDivElement> & {
  side?: "left" | "right";
  variant?: NavbarVariant;
  /** @deprecated This only sets a data attribute. Omit it for built-in styling, or use className or style to customize. */
  size?: NavbarSize;
  /** @deprecated Omit this prop. The component uses the only supported value by default. */
  tone?: NavbarTone;
};

export const MobileMenuContent = forwardRef<
  HTMLDivElement,
  MobileMenuContentProps
>(function MobileMenuContent(
  {
    children,
    className,
    side = "right",
    variant: variantProp,
    size: sizeProp,
    tone: toneProp,
    ...props
  },
  ref,
) {
  const styles = useMobileMenu();
  const variant = variantProp ?? styles?.variant ?? "default";
  const size = sizeProp ?? styles?.size ?? "md";
  const tone = toneProp ?? styles?.tone ?? "default";

  const { contentId, open, setOpen } = styles;
  const portalRoot = usePortalRoot();

  const contentRef = useRef<HTMLDivElement>(null);
  useModalOverlay({
    contentRef,
    open: open && Boolean(portalRoot),
    onEscape: () => setOpen(false),
  });

  if (!open || !portalRoot) {
    return null;
  }

  return createPortal(
    <div className="fixed inset-0 z-50 bg-black/45">
      <div
        aria-hidden="true"
        data-swirski-backdrop=""
        className="absolute inset-0"
      />
      <div
        aria-label="Navigation menu"
        aria-modal="true"
        ref={composeRefs(contentRef, ref)}
        tabIndex={-1}
        className={cn(
          "absolute top-0 flex h-full w-full max-w-sm flex-col border-[length:var(--sw-border-width)] border-[color:var(--sw-color-ink)] bg-[var(--sw-color-surface)] p-5 text-[var(--sw-color-ink)] shadow-[var(--sw-shadow-lg)]",
          side === "right" ? "right-0" : "left-0",
          variant === "compact" && "max-w-xs p-4",
          className,
        )}
        id={contentId}
        role="dialog"
        data-state="open"
        {...swirskiAttrs("mobile-menu-content", { size, tone, variant })}
        {...props}
      >
        <OverlayParentContext.Provider value={contentRef}>
          {children}
        </OverlayParentContext.Provider>
      </div>
    </div>,
    portalRoot,
  );
});

MobileMenuContent.displayName = "MobileMenuContent";

"use client";

import { useControllableState } from "../../hooks/use-controllable-state/useControllableState";
import type { ReactNode } from "react";
import { createContext, useContext, useId } from "react";
import { useNavbarStyles } from "./Navbar";
import type { NavbarSize, NavbarTone, NavbarVariant } from "./Navbar";

type MobileMenuContextValue = {
  contentId: string;
  variant: NavbarVariant;
  size: NavbarSize;
  tone: NavbarTone;
  open: boolean;
  setOpen: (open: boolean) => void;
};

const MobileMenuContext = createContext<MobileMenuContextValue | null>(null);

export type MobileMenuProps = {
  children: ReactNode;
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  variant?: NavbarVariant;
  size?: NavbarSize;
  /** @deprecated Omit this prop. The component uses the only supported value by default. */
  tone?: NavbarTone;
};

export function useMobileMenuStyles() {
  return useContext(MobileMenuContext);
}

export function useMobileMenu() {
  const context = useContext(MobileMenuContext);

  if (!context) {
    throw new Error("MobileMenu components must be used inside MobileMenu.");
  }

  return context;
}

export function MobileMenu({
  children,
  defaultOpen = false,
  open,
  onOpenChange,
  variant: variantProp,
  size: sizeProp,
  tone: toneProp,
}: MobileMenuProps) {
  const navbar = useNavbarStyles();
  const variant = variantProp ?? navbar?.variant ?? "default";
  const size = sizeProp ?? navbar?.size ?? "md";
  const tone = toneProp ?? navbar?.tone ?? "default";
  const contentId = useId();
  const [currentOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });

  return (
    <MobileMenuContext.Provider
      value={{ contentId, open: currentOpen, variant, size, tone, setOpen }}
    >
      {children}
    </MobileMenuContext.Provider>
  );
}

"use client";

